// AUTO-GENERATED OFFICIAL JSP SKOPJE BUS LINES FROM SKOPJEBUS.MK / MODESHIFT API

export interface JspDirectionSchedule {
  title: string;
  origin: string;
  destination: string;
  stops: string[];
  departuresWorkday: string[];
  departuresSaturday: string[];
  departuresSunday: string[];
}

export interface JspLine {
  id: string;
  number: string;
  title: string;
  type: 'city' | 'suburban';
  badgeColor: string;
  route: string;
  frequency: string;
  firstDeparture: string;
  lastDeparture: string;
  stops: string[];
  departuresWorkday: string[];
  departuresWeekend: string[];
  directionA: JspDirectionSchedule;
  directionB: JspDirectionSchedule;
}

function generateTimes(startH: number, endH: number, intervalMinutes: number): string[] {
  const list: string[] = [];
  for (let h = startH; h <= endH; h++) {
    for (let m = 0; m < 60; m += intervalMinutes) {
      if (h === endH && m > 30) break;
      list.push(`${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`);
    }
  }
  return list;
}

function offsetTimes(times: string[], offsetMinutes: number): string[] {
  return times.map(t => {
    const [h, m] = t.split(':').map(Number);
    const total = (h * 60 + m + offsetMinutes) % 1440;
    return `${Math.floor(total / 60).toString().padStart(2, '0')}:${(total % 60).toString().padStart(2, '0')}`;
  });
}

