export const ALL_JSP_LINES: JspLine[] = RAW_LINES.map((def, idx) => {
  const isNight = !!def.isNight || def.number.endsWith('Н') || def.number.endsWith('H');
  const isCity = def.type === 'city' && !isNight;

  const intervalWork = isNight ? 60 : (isCity ? (idx % 3 === 0 ? 10 : (idx % 3 === 1 ? 12 : 15)) : (idx % 2 === 0 ? 25 : 35));
  const intervalSat = isNight ? 60 : (isCity ? intervalWork + 4 : intervalWork + 12);
  const intervalSun = isNight ? 60 : (isCity ? intervalWork + 8 : intervalWork + 20);

  let workA = def.departuresWorkdayA;
  let satA = def.departuresSaturdayA;
  let sunA = def.departuresSundayA;

  if (!workA || workA.length === 0) {
    if (isNight) {
      workA = ['23:30', '00:30', '01:30', '02:30', '03:30'];
      satA = ['23:30', '00:30', '01:30', '02:30', '03:30'];
      sunA = ['23:30', '00:30', '01:30', '02:30', '03:30'];
    } else {
      workA = generateTimes(5, 23, intervalWork);
      satA = generateTimes(6, 22, intervalSat);
      sunA = generateTimes(6, 22, intervalSun);
    }
  }
  if (!satA) satA = offsetTimes(workA, 5);
  if (!sunA) sunA = offsetTimes(workA, 10);

  const workB = offsetTimes(workA, 10);
  const satB = offsetTimes(satA, 10);
  const sunB = offsetTimes(sunA, 10);

  const freq = def.frequency || (isNight ? 'Секој 60 мин' : `Секои ${intervalWork} мин`);

  return {
    id: def.id,
    number: def.number,
    title: def.title,
    type: def.type,
    badgeColor: def.badgeColor,
    route: `${def.originA} ↔ ${def.destA}`,
    frequency: freq,
    firstDeparture: workA[0] || '05:00',
    lastDeparture: workA[workA.length - 1] || '23:30',
    stops: def.stopsA,
    departuresWorkday: workA,
    departuresWeekend: satA,
    directionA: {
      title: `${def.originA} → ${def.destA}`,
      origin: def.originA,
      destination: def.destA,
      stops: def.stopsA,
      departuresWorkday: workA,
      departuresSaturday: satA,
      departuresSunday: sunA
    },
    directionB: {
      title: `${def.originB} → ${def.destB}`,
      origin: def.originB,
      destination: def.destB,
      stops: def.stopsB,
      departuresWorkday: workB,
      departuresSaturday: satB,
      departuresSunday: sunB
    }
  };
});
